import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { createCreditNote } from '../src/credits.js';

test('createCreditNote returns credit note for issued invoice', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 100, reason: 'Defective product', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, true);
  assert.ok(result.value.number);
  assert.equal(result.value.invoiceNumber, invoice.number);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.amount, 100);
  assert.equal(result.value.reason, 'Defective product');
  assert.equal(result.value.date, '2026-10-02');
});

test('createCreditNote fails with NOT_ISSUED for draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 10 }],
  }).value;

  const result = createCreditNote(
    invoice,
    { amount: 100, reason: 'Test', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_ISSUED');
});

test('createCreditNote fails with NOT_ISSUED for paid invoice', () => {
  const invoice = recordPayment(
    recordPayment(
      issueInvoice(
        createInvoice({
          customerId: 'C-001',
          issueDate: '2026-10-01',
          lines: [{ sku: 'STICKER', qty: 10 }],
        }).value,
        [],
      ).value,
      { amount: 100, date: '2026-10-02' },
    ).value,
    { amount: 476, date: '2026-10-03' },
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 50, reason: 'Partial refund', date: '2026-10-04' },
    [],
  );

  assert.equal(result.ok, true);
});

test('createCreditNote fails with AMOUNT_INVALID for non-integer amount', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 100.5, reason: 'Test', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('createCreditNote fails with AMOUNT_INVALID for zero amount', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 0, reason: 'Test', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('createCreditNote fails with AMOUNT_INVALID for negative amount', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: -50, reason: 'Test', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('createCreditNote fails with CREDIT_TOO_HIGH if amount exceeds invoice total', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 10000, reason: 'Test', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CREDIT_TOO_HIGH');
});

test('createCreditNote succeeds with amount equal to invoice total', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 576, reason: 'Full refund', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, true);
  assert.equal(result.value.amount, 576);
});

test('createCreditNote fails with DATE_INVALID for invalid date', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 100, reason: 'Test', date: '2026-13-01' },
    [],
  );

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createCreditNote generates CN- prefixed number', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 100, reason: 'Test', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, true);
  assert.ok(result.value.number.startsWith('CN-2026-'));
});

test('createCreditNote increments counter for multiple credit notes in same year', () => {
  const invoice1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    ['INV-2026-0001'],
  ).value;

  const invoice2 = issueInvoice(
