      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 100, reason: 'Test', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, true);
  assert.ok(result.value.number.startsWith('CN-2026-'));
});

test('createCreditNote increments counter for multiple credit notes in same year', () => {
  const invoice1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const invoice2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-05',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [invoice1.number],
  ).value;

  const cn1 = createCreditNote(
    invoice1,
    { amount: 100, reason: 'Test', date: '2026-10-02' },
    [],
  ).value;

  const cn2 = createCreditNote(
    invoice2,
    { amount: 50, reason: 'Test', date: '2026-10-06' },
    [cn1.number],
  ).value;

  assert.equal(cn1.number, 'CN-2026-0001');
  assert.equal(cn2.number, 'CN-2026-0002');
});

test('createCreditNote restarts counter for different year', () => {
  const invoiceOldYear = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    ['INV-2025-0001'],
  ).value;

  const invoiceNewYear = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    ['INV-2026-0001'],
  ).value;

  const cn2025 = createCreditNote(
    invoiceOldYear,
    { amount: 100, reason: 'Test', date: '2025-10-02' },
    [],
  ).value;

  const cn2026 = createCreditNote(
    invoiceNewYear,
    { amount: 100, reason: 'Test', date: '2026-10-02' },
    [cn2025.number],
  ).value;

  assert.equal(cn2025.number, 'CN-2025-0001');
  assert.equal(cn2026.number, 'CN-2026-0001');
});

test('createCreditNote does not mutate input invoice', () => {
  const originalInvoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const invoiceCopy = JSON.parse(JSON.stringify(originalInvoice));

  createCreditNote(
    originalInvoice,
    { amount: 100, reason: 'Test', date: '2026-10-02' },
    [],
  );

  assert.deepEqual(originalInvoice, invoiceCopy);
});

test('createCreditNote works on partially_paid invoice', () => {
  const invoice = recordPayment(
    issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-01',
        lines: [{ sku: 'STICKER', qty: 10 }],
      }).value,
      [],
    ).value,
    { amount: 200, date: '2026-10-02' },
  ).value;

  assert.equal(invoice.status, 'partially_paid');

  const result = createCreditNote(
    invoice,
    { amount: 100, reason: 'Partial refund', date: '2026-10-03' },
    [],
  );

  assert.equal(result.ok, true);
});

test('createCreditNote returns correct structure', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    [],
  ).value;

  const result = createCreditNote(
    invoice,
    { amount: 100, reason: 'Test refund', date: '2026-10-02' },
    [],
  );

  assert.equal(result.ok, true);
  const cn = result.value;
  assert.ok(cn.number);
  assert.equal(cn.invoiceNumber, invoice.number);
  assert.equal(cn.customerId, 'C-001');
  assert.equal(cn.amount, 100);
  assert.equal(cn.reason, 'Test refund');
  assert.equal(cn.date, '2026-10-02');
  assert.ok(typeof cn.number === 'string');
  assert.ok(typeof cn.invoiceNumber === 'string');
  assert.ok(typeof cn.customerId === 'string');
  assert.ok(typeof cn.amount === 'number');
  assert.ok(typeof cn.reason === 'string');
  assert.ok(typeof cn.date === 'string');
});

